<script>import Modal from '../../../components/Modal.svelte';let {item=null,onClose,onSave,busy=false}= $props();let title=$state(item?.title||'');let url=$state(item?.url||'');let description=$state(item?.description||'');let error=$state('');async function submit(e){e.preventDefault();if(!title.trim()||!url.trim()){error='Nama dan URL tautan wajib diisi.';return;}try{const normalized=new URL(url);if(!['http:','https:'].includes(normalized.protocol))throw new Error();await onSave({title:title.trim(),url:normalized.href,description:description.trim()});}catch(err){error=err.message==='Invalid URL'?'Masukkan URL yang valid.':(err.message||'URL tidak valid.');}}</script>
<Modal title={item?'Ubah Tautan':'Tambah Tautan'} {onClose}><form onsubmit={submit} class="form-stack"><label for="item-title">Nama tautan</label><input id="item-title" bind:value={title} required maxlength="120" placeholder="GitHub, Instagram, portofolio…"/><label for="item-url">URL</label><input id="item-url" type="url" bind:value={url} required placeholder="https://example.com"/><label for="item-description">Deskripsi (opsional)</label><textarea id="item-description" bind:value={description} rows="2" maxlength="300"></textarea>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button type="button" class="btn btn-light" onclick={onClose}>Batal</button><button class="btn btn-primary" disabled={busy}>{busy?'Menyimpan…':'Simpan tautan'}</button></div></form></Modal>
